CREATE OR REPLACE SEMANTIC VIEW SEM.SV_METER_CONSUMPTION
  TABLES (
    meter_reading  AS CORE.FCT_METER_READING PRIMARY KEY (READING_ID) WITH SYNONYMS ('meter reading', 'meter readings')
      COMMENT = 'Fact at MeterReading grain. Source: CC_AND_B_PROD.METER_READING. Origin: FM Business Layer.MeterReading',
    dt             AS CORE.DIM_DATE PRIMARY KEY (DATE_KEY) WITH SYNONYMS ('date')
      COMMENT = 'Dimension at Date grain. Source: ENERGY_DW.DATE_DIM. Origin: FM Business Layer.Date (conformed across Energy_Billing_Package, Energy_Compliance_Package, Energy_CustomerService_Package, Energy_Finance_Package, Energy_Generation_Package, ...',
    meter          AS CORE.DIM_METER PRIMARY KEY (METER_ID) WITH SYNONYMS ('meter')
      COMMENT = 'Dimension at Meter grain. Source: CC_AND_B_PROD.METER. Origin: FM Business Layer.Meter',
    tariff         AS CORE.DIM_TARIFF PRIMARY KEY (TARIFF_ID) WITH SYNONYMS ('tariff')
      COMMENT = 'Dimension at Tariff grain. Source: CC_AND_B_PROD.TARIFF. Origin: FM Business Layer.Tariff',
    customer       AS CORE.DIM_CUSTOMER PRIMARY KEY (CUSTOMER_ID) WITH SYNONYMS ('customer')
      COMMENT = 'Dimension at Customer grain. Source: ENERGY_DW.CUSTOMER. Origin: FM Business Layer.Customer (conformed across Energy_Billing_Package, Energy_CustomerService_Package)',
    location       AS CORE.DIM_LOCATION PRIMARY KEY (LOCATION_ID) WITH SYNONYMS ('location')
      COMMENT = 'Dimension at Location grain. Source: ENERGY_DW.LOCATION. Origin: FM Business Layer.Location (conformed across Energy_Billing_Package, Energy_Operations_Package)'
  )
  RELATIONSHIPS (
    meter_reading_to_dt AS meter_reading (DATE_KEY) REFERENCES dt (DATE_KEY),
    meter_reading_to_meter AS meter_reading (METER_ID) REFERENCES meter (METER_ID),
    meter_reading_to_tariff AS meter_reading (TARIFF_ID) REFERENCES tariff (TARIFF_ID),
    meter_to_customer AS meter (CUSTOMER_ID) REFERENCES customer (CUSTOMER_ID),
    meter_to_location AS meter (LOCATION_ID) REFERENCES location (LOCATION_ID)
  )
  FACTS (
    meter_reading.co2_estimate_kg AS CO2_ESTIMATE_KG
      COMMENT = 'Estimated CO2 emissions at 0.233 kg/kWh (US EPA average grid emission factor)',
    meter_reading.consumption_kwh AS CONSUMPTION_KWH
      COMMENT = 'Measure ''consumption kwh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.ConsumptionKWh',
    meter_reading.consumption_mwh AS CONSUMPTION_MWH
      COMMENT = 'Measure ''consumption mwh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.ConsumptionMWh',
    meter_reading.off_peak_kwh AS OFF_PEAK_KWH
      COMMENT = 'Measure ''off peak kwh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.OffPeakKWh',
    meter_reading.peak_demand_kw AS PEAK_DEMAND_KW
      COMMENT = 'Measure ''peak demand kw''; default aggregation MAX (semi-additive). Origin: FM Business Layer.MeterReading.PeakDemandKW',
    meter_reading.reactive_kvarh AS REACTIVE_KVARH
      COMMENT = 'Measure ''reactive kvarh''; default aggregation SUM (additive). Origin: FM Business Layer.MeterReading.ReactiveKVARh',
    tariff.demand_charge_rate AS DEMAND_CHARGE_RATE
      COMMENT = 'Measure ''demand charge rate''; default aggregation AVG (non-additive). Origin: FM Business Layer.Tariff.DemandChargeRate',
    tariff.rate_per_kwh AS RATE_PER_KWH
      COMMENT = 'Measure ''rate per kwh''; default aggregation AVG (non-additive). Origin: FM Business Layer.Tariff.RatePerKWh',
    meter_reading.reading_id AS READING_ID
      COMMENT = 'Grain key of FCT_METER_READING'
  )
  DIMENSIONS (
    dt.fiscal_year AS FISCAL_YEAR WITH SYNONYMS ('fiscal year', 'FY')
      COMMENT = 'Attribute ''fiscal year''. Origin: FM Business Layer.Date.FiscalYear',
    dt.full_date AS FULL_DATE WITH SYNONYMS ('full date', 'reading date', 'bill date', 'gen date', 'event date', 'request date')
      COMMENT = 'Attribute ''full date''. Origin: FM Business Layer.Date.FullDate',
    dt.is_weekend AS IS_WEEKEND WITH SYNONYMS ('is weekend')
      COMMENT = 'Attribute ''is weekend''. Origin: FM Business Layer.Date.IsWeekend',
    dt.month_name AS MONTH_NAME WITH SYNONYMS ('month name', 'period')
      COMMENT = 'Attribute ''month name''. Origin: FM Business Layer.Date.MonthName',
    dt.quarter AS QUARTER WITH SYNONYMS ('quarter')
      COMMENT = 'Attribute ''quarter''. Origin: FM Business Layer.Date.Quarter',
    meter.meter_id AS METER_ID WITH SYNONYMS ('meter id')
      COMMENT = 'Identifier ''meter id''. Origin: FM Business Layer.Meter.MeterID',
    meter.is_smart_meter AS IS_SMART_METER WITH SYNONYMS ('is smart meter')
      COMMENT = 'Attribute ''is smart meter''. Origin: FM Business Layer.Meter.IsSmartMeter',
    meter.meter_type AS METER_TYPE WITH SYNONYMS ('meter type')
      COMMENT = 'Attribute ''meter type''. Origin: FM Business Layer.Meter.MeterType',
    tariff.tariff_type AS TARIFF_TYPE WITH SYNONYMS ('tariff type')
      COMMENT = 'Attribute ''tariff type''. Origin: FM Business Layer.Tariff.TariffType',
    customer.customer_id AS CUSTOMER_ID WITH SYNONYMS ('customer id')
      COMMENT = 'Identifier ''customer id''. Origin: FM Business Layer.Customer.CustomerID',
    customer.account_type AS ACCOUNT_TYPE WITH SYNONYMS ('account type')
      COMMENT = 'Attribute ''account type''. Origin: FM Business Layer.Customer.AccountType',
    customer.customer_name AS CUSTOMER_NAME WITH SYNONYMS ('customer name')
      COMMENT = 'Attribute ''customer name''. Origin: FM Business Layer.Customer.CustomerName',
    customer.customer_segment AS CUSTOMER_SEGMENT WITH SYNONYMS ('customer segment')
      COMMENT = 'Attribute ''customer segment''. Origin: FM Business Layer.Customer.CustomerSegment',
    customer.service_tier AS SERVICE_TIER WITH SYNONYMS ('service tier')
      COMMENT = 'Attribute ''service tier''. Origin: inferred from report usage (Energy_Billing_Package). TODO: map from CC_AND_B_PROD (Energy_Billing_Package); not in FM model or catalog',
    location.city AS CITY WITH SYNONYMS ('city')
      COMMENT = 'Attribute ''city''. Origin: FM Business Layer.Location.City',
    location.region AS REGION WITH SYNONYMS ('region')
      COMMENT = 'Attribute ''region''. Origin: FM Business Layer.Location.Region'
  )
  METRICS (
    meter_reading.total_co2_estimate_kg AS SUM(meter_reading.co2_estimate_kg) WITH SYNONYMS ('total co2 estimate kg', 'co2 estimate kg')
      COMMENT = 'SUM of co2 estimate kg (additive; default aggregation from FM)',
    meter_reading.total_consumption_kwh AS SUM(meter_reading.consumption_kwh) WITH SYNONYMS ('total consumption kwh', 'consumption kwh')
      COMMENT = 'SUM of consumption kwh (additive; default aggregation from FM)',
    meter_reading.total_consumption_mwh AS SUM(meter_reading.consumption_mwh) WITH SYNONYMS ('total consumption mwh', 'consumption mwh')
      COMMENT = 'SUM of consumption mwh (additive; default aggregation from FM)',
    meter_reading.total_off_peak_kwh AS SUM(meter_reading.off_peak_kwh) WITH SYNONYMS ('total off peak kwh', 'off peak kwh')
      COMMENT = 'SUM of off peak kwh (additive; default aggregation from FM)',
    meter_reading.max_peak_demand_kw AS MAX(meter_reading.peak_demand_kw) WITH SYNONYMS ('max peak demand kw', 'peak demand kw')
      COMMENT = 'MAX of peak demand kw (semi-additive; default aggregation from FM)',
    meter_reading.total_reactive_kvarh AS SUM(meter_reading.reactive_kvarh) WITH SYNONYMS ('total reactive kvarh', 'reactive kvarh')
      COMMENT = 'SUM of reactive kvarh (additive; default aggregation from FM)',
    meter_reading.peak_off_peak_ratio AS SUM(meter_reading.consumption_kwh) / NULLIF(SUM(meter_reading.off_peak_kwh), 0) WITH SYNONYMS ('peak off peak ratio')
      COMMENT = 'Ratio metric from FM calculation MeterReading.PeakOffPeakRatio (regularAggregate=calculated)',
    meter_reading.meter_reading_count AS COUNT(meter_reading.reading_id) WITH SYNONYMS ('number of meter readings')
      COMMENT = 'Number of meter reading rows',
    tariff.avg_demand_charge_rate AS AVG(tariff.demand_charge_rate) WITH SYNONYMS ('avg demand charge rate', 'demand charge rate')
      COMMENT = 'AVG of demand charge rate (non-additive; default aggregation from FM)',
    tariff.avg_rate_per_kwh AS AVG(tariff.rate_per_kwh) WITH SYNONYMS ('avg rate per kwh', 'rate per kwh')
      COMMENT = 'AVG of rate per kwh (non-additive; default aggregation from FM)'
  )
  COMMENT = 'Metered consumption. Generated by SemLift from Energy_Billing_Package; FM default aggregations enforced';

